//! Build-time brand metadata, generated by `scripts/brand/apply.js` from
//! `brands/<id>/brand.json`. Do not edit by hand; on this branch it carries
//! the Folly Launcher statistics prefix.

/// Prefix prepended to the reported version on the upstream statistics
/// server, as required by LICENSE.EXTRA for modified distributions
/// (e.g. "jlucraft" produces "folly-1.3.1"). Empty for the unmodified
/// upstream build.
pub const STATS_VERSION_PREFIX: &str = "folly";
